mapper.update:
update mxk_apps_jwt_details
set issuer = #{et.issuer}, subject = #{et.subject}, audience = #{et.audience},
    algorithmkey = #{et.algorithmKey}, algorithm = #{et.algorithm}, encryptionmethod = #{et.encryptionMethod},
    signature = #{et.signature}, signaturekey = #{et.signatureKey}, expires = #{et.expires},
    redirecturi = #{et.redirectUri}, jwtname = #{et.jwtName}, tokentype = #{et.tokenType}, instid = #{et.instId}
where id = #{et.id}

mapper.select:
select *
from mxk_apps_jwt_details jd,
     mxk_apps app
where app.instid = jd.instid
  and app.id = #{value}
  and jd.id = #{value}
  and status = 1
  and jd.id = app.id
